text = "Mr. Bennet replied that he had not. Mr. Bennet made no answer."
counts = {}
for word in text.split():
    word = word.strip('.,;:!?"').lower()
    if word in counts:
        counts[word] += 1
    else:
        counts[word] = 1
print(counts["mr"])
print(counts["answer"])
print(len(counts))

